      { id: 6, type: "mcq", q: `The earliest evidence of true copper smelting comes from:`, opts: [`A) Belovode in Serbia`, `B) Çatalhöyük in Turkey`, `C) Oman`, `D) Rio Tinto`], answer: `A`, explanation: `'True smelting appears in the Balkans (Belovode, Serbia) dated 4500 BCE'.` },
      { id: 7, type: "mcq", q: `Oxidised ores such as malachite were preferred because they:`, opts: [`A) were stronger`, `B) contained tin`, `C) produced no slag`, `D) required lower temperatures than sulphide ores`], answer: `D`, explanation: `They 'required lower temperatures (700-800°C) than sulphide ores'.` },
      { id: 8, type: "mcq", q: `The Uluburun shipwreck's cargo of copper and tin could have produced about:`, opts: [`A) 1 ton of bronze`, `B) 11 tons of bronze`, `C) 100 tons of bronze`, `D) 15,000 tons of bronze`], answer: `B`, explanation: `10 tons of copper and 1 ton of tin were 'enough to produce 11 tons of bronze'.` },
      { id: 9, type: "mcq", q: `According to McConnell et al. (2019), Roman-era copper pollution:`, opts: [`A) was negligible`, `B) only affected Spain`, `C) exceeded year-2000 industrial levels in certain lead isotopes`, `D) began in 1200 BCE`], answer: `C`, explanation: `'Roman-era pollution exceeded 2000 CE industrial levels in certain lead isotopes'.` },
      { id: 10, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Copper alloyed with ___ produces bronze.`, answer: `tin`, explanation: `Alloying 'transformed copper into bronze (with tin) around 3200 BCE'.` },
      { id: 11, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Early smelters extracted copper in clay-lined pits known as ___.`, answer: `bowl furnaces`, acceptedAnswers: [`bowl furnace`], explanation: `'Early smelters used 'bowl furnaces' – clay-lined pits with charcoal fuel'.` },
      { id: 12, type: "short_answer", q: `What glassy waste product floated on the molten copper?`, answer: `slag`, explanation: `'Slag, a glassy waste product, floated on the melt'.` },
      { id: 13, type: "short_answer", q: `How many tons of copper did the Roman Empire mine annually from Rio Tinto?`, answer: `15,000 tons`, acceptedAnswers: [`15,000`, `15000 tons`], explanation: `'The Roman Empire mined 15,000 tons annually from Rio Tinto (Spain)'.` }
