      { id: 5, type: "tfng", q: `Roman glass beads never travelled beyond Europe.`, answer: `FALSE`, explanation: `Roman glass beads 'reached Scandinavia, sub-Saharan Africa, and India'.` },
      { id: 6, type: "mcq", q: `The oldest known beads were made from:`, opts: [`A) Nassarius shells`, `B) carnelian`, `C) lapis lazuli`, `D) glass`], answer: `A`, explanation: `The oldest beads are 'Nassarius shell beads from Skhul Cave... and Blombos Cave'.` },
      { id: 7, type: "mcq", q: `Indus Valley craftsmen deepened the colour of carnelian beads by:`, opts: [`A) glazing them`, `B) heat-treating them at 500°C`, `C) coating them in cobalt`, `D) soaking them in cacao`], answer: `B`, explanation: `Carnelian 'was heat-treated at 500°C to deepen colour'.` },
      { id: 8, type: "mcq", q: `A 2019 British Museum study matched 95% of Egyptian lapis lazuli to:`, opts: [`A) Mohenjo-Daro`, `B) Blombos Cave`, `C) the Sar-i Sang mine`, `D) Swedish workshops`], answer: `C`, explanation: `It matched '95% of lapis lazuli artefacts in Egypt to the Sar-i Sang mine'.` },
      { id: 9, type: "mcq", q: `In pre-Columbian Mesoamerica, a single jadeite bead was worth:`, opts: [`A) 10 cacao beans`, `B) 100 cacao beans`, `C) 1,000 cacao beans`, `D) 10,000 cacao beans`], answer: `D`, explanation: `'A single jadeite bead was worth 10,000 cacao beans'.` },
      { id: 10, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Indus Valley beads were drilled using diamond-tipped ___ drills.`, answer: `bow`, explanation: `Carnelian was 'drilled with diamond-tipped bow drills'.` },
      { id: 11, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Glazed quartz beads from Egypt, known as ___ beads, spread to Mycenaean Greece.`, answer: `faience`, explanation: `'Faience beads (glazed quartz) from Egypt spread to Mycenaean Greece'.` },
      { id: 12, type: "short_answer", q: `Which blue stone from Afghanistan appears in Tutankhamun's mask?`, answer: `lapis lazuli`, explanation: `'Lapis lazuli from Afghanistan's Badakhshan mines appears in Egyptian tombs (Tutankhamun's mask)'.` },
      { id: 13, type: "short_answer", q: `How many beads per hour could a skilled craftsman drill, according to experimental archaeology?`, answer: `10`, acceptedAnswers: [`ten`, `10 beads`], explanation: `'A skilled craftsman could drill 10 beads per hour'.` }
