      { id: 3, type: "tfng", q: `Most accidental cable cuts are caused by anchors or fishing trawlers.`, answer: `TRUE`, explanation: `Cables are 'often cut by anchors or fishing trawlers (over 100 accidental cuts annually)'.` },
      { id: 4, type: "tfng", q: `Repairing a cut cable typically takes longer in the Pacific than in the Atlantic.`, answer: `NOT GIVEN`, explanation: `Repair times are mentioned generally, but no Pacific-versus-Atlantic comparison is made.` },
      { id: 5, type: "tfng", q: `Undersea cables are heavily protected against deliberate damage.`, answer: `FALSE`, explanation: `'Despite their importance, they are poorly protected'.` },
      { id: 6, type: "mcq", q: `Undersea fibre-optic cables carry what proportion of intercontinental internet traffic?`, opts: [`A) about half`, `B) about 30%`, `C) over 99%`, `D) 0.5%`], answer: `C`, explanation: `'Over 99% of intercontinental internet traffic flows through... cables'.` },
      { id: 7, type: "mcq", q: `The 2019 EastWest Institute study estimated that cutting cables at three choke points would cost the global economy:`, opts: [`A) $10 trillion per day`, `B) $7 billion per day`, `C) $20 billion in total`, `D) nothing`], answer: `B`, explanation: `A coordinated cut 'would cost the global economy $7 billion per day'.` },
      { id: 8, type: "mcq", q: `International law prohibiting intentional cable damage falls under:`, opts: [`A) the EU AI Act`, `B) INTERREG`, `C) the Choke Point Analysis`, `D) UNCLOS`], answer: `D`, explanation: `'International law under the UN Convention on the Law of the Sea (UNCLOS) prohibits intentional cable damage'.` },
      { id: 9, type: "mcq", q: `A 2022 analysis found that 60% of new cables are owned by:`, opts: [`A) content providers such as Google and Amazon`, `B) national governments`, `C) the US Navy`, `D) fishing consortia`], answer: `A`, explanation: `'60% of new cables are owned by content providers, not telcos'.` },
      { id: 10, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `The world's undersea cables stretch about ___ million kilometres along the ocean floor.`, answer: `1.4`, acceptedAnswers: [`1.4 million`], explanation: `Traffic flows through '1.4 million kilometres of fibre-optic cables'.` },
      { id: 11, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Russian ___-class surveillance ships have loitered near cable landing stations.`, answer: `Yantar`, explanation: `'Russian surveillance ships (Yantar-class) have been observed loitering near cable landing stations'.` },
      { id: 12, type: "short_answer", q: `Roughly how many accidental cable cuts occur each year, mostly from anchors and trawlers?`, answer: `over 100`, acceptedAnswers: [`100`], explanation: `There are 'over 100 accidental cuts annually'.` },
      { id: 13, type: "short_answer", q: `What is the US Navy's 2023 unmanned cable-monitoring submarine programme called?`, answer: `Manta Ray`, acceptedAnswers: [`the Manta Ray`], explanation: `'The US Navy's 'Manta Ray' submarine programme (2023) deploys unmanned vehicles for cable monitoring and repair'.` }
