      { id: 4, type: "tfng", q: `In Kiecolt-Glaser's 1991 study, medical students had reduced natural killer cell activity during exam week.`, answer: `TRUE`, explanation: `Students 'had lower natural killer (NK) cell activity during exam week than during vacation – a 30% decrease'.` },
      { id: 5, type: "tfng", q: `Mindfulness-based stress reduction increased pro-inflammatory gene expression in caregivers.`, answer: `FALSE`, explanation: `MBSR produced 'a 25% reduction in pro-inflammatory gene expression'.` },
      { id: 6, type: "mcq", q: `Psychoneuroimmunology studies the links between psychological states, the nervous system, and:`, opts: [`A) immune function`, `B) the digestive system`, `C) muscle growth`, `D) bone density`], answer: `A`, explanation: `PNI studies links between 'psychological states, the nervous system, and immune function'.` },
      { id: 7, type: "mcq", q: `Chronic stress shifts the immune balance toward Th2 responses, reducing resistance to:`, opts: [`A) bacteria only`, `B) all pathogens equally`, `C) parasites`, `D) intracellular pathogens such as viruses`], answer: `D`, explanation: `The Th2 shift reduces 'resistance to intracellular pathogens (viruses, cancer)'.` },
      { id: 8, type: "mcq", q: `The 2020 longitudinal study found that each one-point rise on the Perceived Stress Scale raised heart disease risk by:`, opts: [`A) 30%`, `B) 40%`, `C) 12%`, `D) 25%`], answer: `C`, explanation: `Each one-point increase 'raised heart disease risk by 12%'.` },
      { id: 9, type: "mcq", q: `A 2019 RCT found that mindfulness-based stress reduction in cancer caregivers produced:`, opts: [`A) no measurable change`, `B) a 25% reduction in pro-inflammatory gene expression`, `C) increased cortisol`, `D) higher infection rates`], answer: `B`, explanation: `It found 'a 25% reduction in pro-inflammatory gene expression after 8 weeks'.` },
      { id: 10, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Chronic stress releases ___, which suppress immune activity.`, answer: `cortisol`, acceptedAnswers: [`glucocorticoids`], explanation: `Stress is 'releasing cortisol. Glucocorticoids suppress immune activity'.` },
      { id: 11, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `Childhood adversity produces epigenetic changes in the glucocorticoid receptor gene known as ___.`, answer: `NR3C1`, explanation: `Adversity produces 'epigenetic changes in glucocorticoid receptor genes (NR3C1)'.` },
      { id: 12, type: "short_answer", q: `Which immune cells showed reduced activity in stressed medical students?`, answer: `NK cells`, acceptedAnswers: [`natural killer cells`, `natural killer`], explanation: `Students had 'lower natural killer (NK) cell activity'.` },
      { id: 13, type: "short_answer", q: `Which inflammatory pathway does stress activate to upregulate cytokines?`, answer: `NF-κB`, acceptedAnswers: [`NF-kB`, `NF-κB pathway`], explanation: `Stress upregulates cytokines 'through NF-κB pathway activation'.` }
