      { id: 9, type: "mcq", q: `On Wikipedia, editors who received 'WikiLove' messages subsequently:`, opts: [`A) edited 50% more pages`, `B) stopped editing`, `C) demanded payment`, `D) deleted articles`], answer: `A`, explanation: `Editors who received WikiLove 'edited 50% more pages subsequently'.` },
      { id: 10, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `The Trobriand Islanders' ceremonial exchange of shell valuables is called the ___ ring.`, answer: `kula`, explanation: `'The kula ring – ceremonial exchange of shell necklaces and armbands'.` },
      { id: 11, type: "sentence_completion", q: `Complete the sentence.`, sentenceTemplate: `In competitive gift-giving, Pacific Northwest chiefs hold a ___ to assert status.`, answer: `potlatch`, explanation: `'The potlatch... involves competitive gift-giving... to assert status'.` },
      { id: 12, type: "short_answer", q: `Who wrote the 1925 essay 'The Gift'?`, answer: `Marcel Mauss`, acceptedAnswers: [`Mauss`], explanation: `'Marcel Mauss's 1925 essay 'The Gift''.` },
      { id: 13, type: "short_answer", q: `Across how many islands does the kula ring establish alliances?`, answer: `18`, acceptedAnswers: [`eighteen`, `18 islands`], explanation: `The kula ring 'establishes alliances across 18 islands'.` }
